sql_gerado:
SELECT COUNT(*) AS num_clientes_sp
FROM clientes
WHERE estado = 'São Paulo';

SELECT região, COUNT(*) AS quantidade
FROM clientes
GROUP BY região;

SELECT AVG(valor) AS media_valor_pedido
FROM pedidos
WHERE status = 'Não Cancelado';

SELECT strftime('%Y', data_venda) AS ano, SUM(preco_venda * quantidade_vendida) AS faturamento_total
FROM vendas
GROUP BY ano;

SELECT CAST(SUM(CASE WHEN T2.Categoria = 'Eletrônicos' THEN T1.ValorTotal ELSE 0 END) AS REAL) * 100 / SUM(T1.ValorTotal) AS PercentualEletronicos
FROM Vendas AS T1
JOIN Produtos AS T2 ON T1.ProdutoID = T2.ID;

SELECT COUNT(*) 
FROM pedidos 
WHERE status = 'confirmado' AND valor_total > 1000;
